for (const type of Object.keys(extraPrompts)) {
  pools[type].push(...extraPrompts[type].map(item => item.text));
}

export class PromptPicker {
 constructor(random = Math.random) { this.random = random; this.recent = []; }
 next() {
   const r = this.random(); const type = r < .45 ? 'rest' : r < .65 ? 'reflect' : 'surprise';
   const available = pools[type].filter(p => !this.recent.includes(p));
   const text = available[Math.floor(this.random() * available.length)];
   this.recent.push(text); if (this.recent.length > 24) this.recent.shift();
   return { type, text };
 }
}
